import math

def is_power_of_6(N):
    if N <= 0:
        return False
    if N == 1:
        return True # Though unlikely for our constraints

    while N % 6 == 0:
        N //= 6

    return N == 1

def solve_equation(max_ab):
    solutions = []
    print(f"Searching for solutions (a, b, c) to 2^a + 3^b + 1 = 6^c for a, b <= {max_ab}...")

    for a in range(1, max_ab + 1):
        for b in range(1, max_ab + 1):
            N = (2**a) + (3**b) + 1

            if is_power_of_6(N):
                # Find c such that 6^c = N
                c = round(math.log(N, 6))

                # Double check that 6^c actually equals N
                if 6**c == N:
                    solutions.append((a, b, c))
                    print(f"Found solution: ({a}, {b}, {c})")

    return solutions

# Extend search limit to a, b <= 20 as requested
max_limit = 20
all_solutions = solve_equation(max_limit)

print("\n--- Summary ---")
print(f"Total solutions found up to a, b <= {max_limit}: {len(all_solutions)}")
print("List of all solutions found:")
for sol in all_solutions:
    print(sol)

